package vn.svframe.svframelib.api.crafting.outputs; import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.crafting.recipes.*; import vn.svframe.svframelib.api.crafting.recipes.vmp.VanillaInventoryMapping; import net.minecraft.item.ItemStack; import net.minecraft.server.network.ServerPlayerEntity; import java.util.*; public class MROCommand extends SVFrameRecipeOutput { private final String name; private final ArrayList<String> description=new ArrayList<>(); private final SVFrameIngredient display; private final ArrayList<String> commands=new ArrayList<>(); public MROCommand(String name,String description,SVFrameIngredient display,String... commands){this.name=name;this.display=display;if(description!=null)this.description.add(description);this.commands.addAll(Arrays.asList(commands));if(display==null)throw new IllegalArgumentException("display");} public String getDisplayedName(){return name;} public ArrayList<String> getDescription(){return new ArrayList<>(description);} public SVFrameIngredient getDisplay(){return display;} public ArrayList<String> getCommands(){return new ArrayList<>(commands);} public ItemStack getDisplayItem(){return display.getRandomDisplayItem(null);} public SVFrameRecipeInventory applyDisplay(SVFrameBlueprintInventory input,ServerPlayerEntity player,VanillaInventoryMapping mapping){SVFrameRecipeInventory i=new SVFrameRecipeInventory();i.setItemAt(0,0,getDisplayItem());return i;} public void applyResult(SVFrameRecipeInventory result,SVFrameBlueprintInventory input,SVFrameCachedResult cache,ServerPlayerEntity player,VanillaInventoryMapping mapping,int amount){if(player==null||player.getServer()==null)return;for(int n=0;n<Math.max(1,amount);n++)for(String cmd:commands){String parsed=cmd.replace("<player>",player.getName().getString());player.getServer().getCommandManager().executeWithPrefix(player.getServer().getCommandSource(),parsed);}} }
